function mount(host,opts){
  opts=opts||{};if(host.__eci)return host.__eci;
  var base=opts.base||DEFAULT_BASE;
  if(!siteHasInter()&&!document.querySelector('link[data-eci-font]')){var l=document.createElement('link');l.rel='stylesheet';l.href=FONT;l.setAttribute('data-eci-font','');document.head.appendChild(l);}
  var root=host.shadowRoot||host.attachShadow({mode:'open'});
  root.innerHTML='<style>'+CSS+'</style>'+HTML;
  host.__eci=run(root,base).catch(function(err){var p=root.getElementById('panel');if(p)p.textContent='The data did not load. Reload the page to try again.';console.error(err);});
  return host.__eci;
}
window.EybnaComplianceIndex={mount:mount};
